INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a415842b-1512-545a-b59c-04c8f958420a','TEXT','The Tiny Ferry — A Different Day','When Zoe first became interested in the model ferry, the task at the river workshop looked routine. Yet on Tuesday, an unexpected problem appeared. A hurried solution would have been possible, but Zoe suspected that the first explanation was too simple. Instead, Zoe treated the problem as a small investigation.
